package com.bank.cost;

import java.util.*;
import java.util.logging.*;

public class CostOptimizerDemo {
    private static final Logger log = Logger.getLogger("CostOptimizer");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CostOptimizer optimizer = new CostOptimizer();

        List<CostItem> items = List.of(
            new CostItem("core-ledger", "compute", 24, false, 70, false, false),
            new CostItem("fraud-batch", "compute", 2, true, 15, false, false),
            new CostItem("web-server", "compute", 24, false, 10, false, false), // low CPU → right-size
            new CostItem("old-statements", "storage", 0, false, 0, true, false),
            new CostItem("dev-environment", "compute", 24, false, 20, false, true)); // non-prod

        for (CostItem it : items) {
            String rec = optimizer.recommend(it);
            log.info(() -> it.name() + " -> " + rec + " [est. saving " + optimizer.estimateSaving(it) + "]");
        }
    }
}

// ─── Would be in CostOptimizer.java ───
class CostOptimizer {
    String recommend(CostItem it) {
        if ("storage".equals(it.type())) {
            return "S3 lifecycle: Standard → Standard-IA → Glacier → expire";
        }
        if (it.nonProd()) {
            return "Schedule shutdown nights/weekends (runs ~1/3 of the week)";
        }
        if (it.interruptible()) {
            return "Spot Instances (fault-tolerant batch, up to ~90% off)";
        }
        if (it.cpuUtilization() < 20) {
            return "Right-size to a smaller instance (low CPU in CloudWatch)";
        }
        if (it.steadyHoursPerDay() >= 20) {
            return "Savings Plan / Reserved Instances (steady, predictable, up to ~70% off)";
        }
        return "On-demand (keep flexible)";
    }

    String estimateSaving(CostItem it) {
        if ("storage".equals(it.type())) return "large (cold tiers vs Standard)";
        if (it.nonProd()) return "~65% (off nights/weekends)";
        if (it.interruptible()) return "up to ~90%";
        if (it.cpuUtilization() < 20) return "~50% (half-size instance)";
        if (it.steadyHoursPerDay() >= 20) return "up to ~70% (1-3yr commit)";
        return "0%";
    }
}

// ─── Would be in CostItem.java ───
class CostItem {
    private final String name;
    private final String type;            // compute or storage
    private final int steadyHoursPerDay;
    private final boolean interruptible;
    private final int cpuUtilization;     // percent
    private final boolean coldStorage;
    private final boolean nonProd;
    CostItem(String name, String type, int steadyHoursPerDay, boolean interruptible,
             int cpuUtilization, boolean coldStorage, boolean nonProd) {
            this.name = name;
            this.type = type
            this.steadyHoursPerDay = steadyHoursPerDay;
            this.interruptible = interruptible;
            this.cpuUtilization = cpuUtilization;
            this.coldStorage = coldStorage;
            this.nonProd = nonProd;
    }
    String name() { return name; }
    String type() { return type; }
    int steadyHoursPerDay() { return steadyHoursPerDay; }
    boolean interruptible() { return interruptible; }
    int cpuUtilization() { return cpuUtilization; }
    boolean coldStorage() { return coldStorage; }
    boolean nonProd() { return nonProd; }
}

